/**
 * @file    test_crc.c
 * @brief   Unit tests for the AUTOSAR Crc Library.
 *
 * Expected values come from test/support/Crc_TestVectors.h, which is generated by
 * tools/crc_reference.py -- an independent bit-at-a-time model that first proves
 * itself against each profile's published check constant. The C code is therefore
 * never compared against itself.
 *
 * @req SWREQ-INT-0010, SWREQ-INT-0011, SWREQ-INT-0012
 * @verifies TS-CRC-001 .. TS-CRC-009
 *
 * @copyright
 * Copyright (c) 2024-2026 Abdullah Shabbir. All rights reserved.
 * SPDX-License-Identifier: Proprietary
 */

