/*==================================================================================================
 *  TS-CRC-001 .. 006 : every profile reproduces every generated vector
 *================================================================================================*/

/** @test TS-CRC-001 CRC-8 (SAE J1850) matches the reference model on all vectors. */
static void test_Crc8_MatchesReferenceVectors(void)
{
    uint32 i;
    for (i = 0u; i < CRC_TEST_VECTOR_COUNT; i++)
    {
        const Crc_TestVectorType *v = &Crc_TestVectors[i];
        const uint8 actual = Crc_CalculateCRC8(v->data, v->length, 0u, TRUE);
        TEST_ASSERT_EQUAL_HEX8_MESSAGE(v->expCrc8, actual, v->name);
    }
}

